set -eu
python3 - <<'PY'
import json, urllib.request
base="http://127.0.0.1:8787"
rid="run_mv5agtgf_96b706c70a"
keys=("run_id","state","job_status","status","phase","last_execution_failure","reason","code","stage","role","retryable","retry_count","last_error","latest_error","error","current_step","next_action","blocked_reason","timestamp")
for name in ("status","inspect"):
    url=f"{base}/v1/{name}/{rid}"
    print(f"DEBUGAI_{name.upper()}_BEGIN")
    try:
        with urllib.request.urlopen(url,timeout=10) as response:
            obj=json.load(response)
            print("HTTP=",response.status)
        def walk(value, prefix="", depth=0):
            if depth>5: return
            if isinstance(value,dict):
                for k,v in value.items():
                    if k in keys:
                        raw=json.dumps(v,ensure_ascii=True)
                        print((prefix+"."+k).strip(".")+"="+raw[:700])
                    elif isinstance(v,(dict,list)):
                        walk(v,(prefix+"."+k).strip("."),depth+1)
            elif isinstance(value,list):
                for i,v in enumerate(value[:4]):walk(v,prefix+f"[{i}]",depth+1)
        walk(obj)
        print("TOP_KEYS="+",".join(sorted(obj)[:50]))
    except Exception as e:
        print("ERROR_TYPE="+type(e).__name__)
        if hasattr(e,"code"): print("HTTP_ERROR="+str(e.code))
    print(f"DEBUGAI_{name.upper()}_END")
PY
